function verifyRepositoryExists(allow_auto_merge, allow_merge_commit, allow_rebase_merge, allow_squash_merge, auto_init, delete_branch_on_merge, description, gitignore_template, has_discussions, has_downloads, has_issues, has_projects, has_wiki, homepage, is_template, license_template, merge_commit_message, merge_commit_title, name, org, owner, private, ref, repo, repository_id, squash_merge_commit_message, squash_merge_commit_title, team_id, template_owner, template_repo, username) {
  var url = "/user/repos";
  var description = "Verify Repository with owner " + owner + " exists";
  svc.get(url, {
    expectedResponseCodes: [200],
    parameters: { description: description },
    callback: function(response) {
      var items = JSON.parse(response.body);
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          if (String(items[i].owner) === String(owner)) {
            return pvg.success("Repository exists");
          }
        }
      }
      return pvg.fail("Expected Repository to exist but it does not");
    }
  });
}

