function matchAddedHostedRunner(enable_static_ip, hosted_runner_id, image, maximum_runners, name, org, runner_group_id, size) {
  var expectedDesc = "Create hosted runner " + name + " in organization " + org;
  return matchSuccess(expectedDesc);
}

function waitForAnyHostedRunnerAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ hosted\ runner\ (.+)\ in\ organization\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ hosted\ runner\ (.+)\ in\ organization\ (.+)$/);
  var captures = m.slice(1);
  var names = ["name", "org"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getHostedRunnerAddedEvent(keyVal) {
  return bp.EventSet("AddHostedRunner:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.org) === String(keyVal);
  });
}

function matchAnyHostedRunnerAdded() {
  return bp.EventSet("matchAnyHostedRunnerAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.org !== undefined && e.name.indexOf("Create hosted runner") > -1;
  });
}

function waitForHostedRunnerAdded(enable_static_ip, hosted_runner_id, image, maximum_runners, name, org, runner_group_id, size) {
  var expectedDesc = "Create hosted runner " + name + " in organization " + org;
  waitFor(matchSuccess(expectedDesc));
}

function matchDeletedHostedRunner(enable_static_ip, hosted_runner_id, image, maximum_runners, name, org, runner_group_id, size) {
  var expectedDesc = "Delete hosted runner " + hosted_runner_id + " in organization " + org;
  return bp.EventSet("matchDeletedHostedRunner", function(e) {
      return !!(e.data && e.data.parameters && e.data.parameters.description === expectedDesc);
  });
}

function waitForAnyHostedRunnerDeleted() {
  var ev = waitFor(matchesDescriptionRegex(/^Delete\ hosted\ runner\ (.+)\ in\ organization\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Delete\ hosted\ runner\ (.+)\ in\ organization\ (.+)$/);
  var captures = m.slice(1);
  var names = ["hosted_runner_id", "org"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

