// ---- Entity: pull request ----

function createPullRequest(base, body, draft, head, head_repo, issue, maintainer_can_modify, owner, pull_number, repo, title) {
  var url = "/repos/" + owner + "/" + repo + "/pulls";
  var description = "Create pull request with head " + head + " and base " + base;
  var body = {
    "base": String(base),
    "body": String(body),
    "draft": String(draft),
    "head": String(head),
    "head_repo": String(head_repo),
    "issue": String(issue),
    "maintainer_can_modify": String(maintainer_can_modify),
    "owner": String(owner),
    "repo": String(repo),
    "title": String(title),
  };
  svc.post(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [201, 403, 422],
    parameters: {
      description: description,
      owner: String(owner)
      , pull_number: String(pull_number)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

function getPullRequest(base, body, draft, head, head_repo, issue, maintainer_can_modify, owner, pull_number, repo, title) {
  var url = "/repos/" + owner + "/" + repo + "/pulls/" + pull_number;
  var description = "Get pull request " + pull_number;
  var body = undefined;
  svc.get(url, {
    parameters: { description: description },
    expectedResponseCodes: [200, 304, 404, 406, 500, 503]
  });
}

function updatePullRequest(base, body, draft, head, head_repo, issue, maintainer_can_modify, owner, pull_number, repo, title) {
  var url = "/repos/" + owner + "/" + repo + "/pulls/" + pull_number;
  var description = "Update pull request " + pull_number + " with title " + title + " and state {state}";
  var body = {
    "base": String(base),
    "body": String(body),
    "maintainer_can_modify": String(maintainer_can_modify),
    "owner": String(owner),
    "pull_number": String(pull_number),
    "repo": String(repo),
    "state": "state_" + owner,
    "title": String(title),
  };
  svc.patch(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [200, 403, 422],
    parameters: {
      description: description,
      owner: String(owner)
      , pull_number: String(pull_number)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

