function waitForAnyProjectItemAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Add\ item\ of\ type\ (.+)\ with\ id\ (.+)\ to\ project\ (.+)\ for\ user\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Add\ item\ of\ type\ (.+)\ with\ id\ (.+)\ to\ project\ (.+)\ for\ user\ (.+)$/);
  var captures = m.slice(1);
  var names = ["type", "id", "project_number", "username"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getProjectItemAddedEvent(keyVal) {
  return bp.EventSet("AddProjectItem:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.username) === String(keyVal);
  });
}

function matchAnyProjectItemAdded() {
  return bp.EventSet("matchAnyProjectItemAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.username !== undefined && e.name.indexOf("Create project item") > -1;
  });
}

