// ---- Entity: repository security advisory ----

function createRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories";
  var description = "Create repository security advisory in repo " + repo + " owned by " + owner;
  var body = {
    "credits": String(credits),
    "cve_id": String(cve_id),
    "cvss_vector_string": String(cvss_vector_string),
    "cwe_ids": String(cwe_ids),
    "description": String(description),
    "owner": String(owner),
    "repo": String(repo),
    "severity": String(severity),
    "start_private_fork": String(start_private_fork),
    "summary": String(summary),
    "vulnerabilities": String(vulnerabilities),
  };
  svc.post(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [201, 403, 404, 422],
    parameters: {
      description: description,
      owner: String(owner)
      , cve_id: String(cve_id)
      , ghsa_id: String(ghsa_id)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

function getRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories/" + ghsa_id;
  var description = "Get repository security advisory " + ghsa_id + " in repo " + repo + " owned by " + owner;
  var body = undefined;
  svc.get(url, {
    parameters: { description: description },
    expectedResponseCodes: [200, 403, 404]
  });
}

function updateRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories/" + ghsa_id;
  var description = "Update repository security advisory " + ghsa_id + " in repo " + repo + " owned by " + owner;
  var body = {
    "collaborating_teams": [],
    "collaborating_users": [],
    "credits": String(credits),
    "cve_id": String(cve_id),
    "cvss_vector_string": String(cvss_vector_string),
    "cwe_ids": String(cwe_ids),
    "description": String(description),
    "ghsa_id": String(ghsa_id),
    "owner": String(owner),
    "repo": String(repo),
    "severity": String(severity),
    "state": "state_" + owner,
    "summary": String(summary),
    "vulnerabilities": String(vulnerabilities),
  };
  svc.patch(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [200, 403, 404, 422],
    parameters: {
      description: description,
      owner: String(owner)
      , cve_id: String(cve_id)
      , ghsa_id: String(ghsa_id)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

function tryToAddExistingRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  updateRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities);
}

function verifyRepositorySecurityAdvisoryExists(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories";
  var description = "Verify RepositorySecurityAdvisory with owner " + owner + " exists";
  svc.get(url, {
    expectedResponseCodes: [200],
    parameters: { description: description },
    callback: function(response) {
      var items = JSON.parse(response.body);
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          if (String(items[i].owner) === String(owner)) {
            return pvg.success("RepositorySecurityAdvisory exists");
          }
        }
      }
      return pvg.fail("Expected RepositorySecurityAdvisory to exist but it does not");
    }
  });
}

function verifyRepositorySecurityAdvisoryDoesNotExist(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories";
  var description = "Verify RepositorySecurityAdvisory with owner " + owner + " does not exist";
  svc.get(url, {
    expectedResponseCodes: [200],
    parameters: { description: description },
    callback: function(response) {
      var items = JSON.parse(response.body);
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          if (String(items[i].owner) === String(owner)) {
            return pvg.fail("Expected RepositorySecurityAdvisory to not exist but it does");
          }
        }
      }
      return pvg.success("RepositorySecurityAdvisory does not exist");
    }
  });
}

function matchAddedRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var expectedDesc = "Create repository security advisory in repo " + repo + " owned by " + owner;
  return matchSuccess(expectedDesc);
}

function waitForAnyRepositorySecurityAdvisoryAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ repository\ security\ advisory\ in\ repo\ (.+)\ owned\ by\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ repository\ security\ advisory\ in\ repo\ (.+)\ owned\ by\ (.+)$/);
  var captures = m.slice(1);
  var names = ["repo", "owner"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getRepositorySecurityAdvisoryAddedEvent(keyVal) {
  return bp.EventSet("AddRepositorySecurityAdvisory:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.owner) === String(keyVal);
  });
}

function matchAnyRepositorySecurityAdvisoryAdded() {
  return bp.EventSet("matchAnyRepositorySecurityAdvisoryAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.owner !== undefined && e.name.indexOf("Create repository security advisory") > -1;
  });
}

function waitForRepositorySecurityAdvisoryAdded(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, summary, vulnerabilities) {
  var expectedDesc = "Create repository security advisory in repo " + repo + " owned by " + owner;
  waitFor(matchSuccess(expectedDesc));
}

